// ============================================================================
// research-report-cn / rr_lib.js
//
// Layout library for Chinese research-group-style decks (组会汇报 / 论文精读 / 综述).
// DO NOT EDIT THIS FILE PER DECK. Write a separate deck script (see
// example_deck.js) that calls createDeck() and the slide methods below.
//
// What the library guarantees so the deck script doesn't have to:
//   * Chinese renders in 宋体, Latin/digits in Times New Roman, inside the SAME
//     text run (every run gets latin=Times New Roman + ea=宋体 at save time).
//   * {{keyword}} is parsed everywhere: red bold inside stamp claims, bold
//     elsewhere. Braces never leak into the file.
//   * Every slide's content is measured before drawing. Lists / tables / TOCs
//     shrink spacing and font a little if needed; if they still don't fit, a
//     WARNING with the slide number is printed. Fix every warning (split the
//     page or cut words) before delivering.
//   * Page numbers, TOC highlighting and badge are automatic.
// ============================================================================

const fs = require("fs");
const path = require("path");
const pptxgen = require("pptxgenjs");

function loadJSZip() {
  try { return require("jszip"); } catch (e) { /* fall through */ }
  const base = path.dirname(require.resolve("pptxgenjs"));
  return require(require.resolve("jszip", { paths: [base] }));
}

// ---------------------------------------------------------------- constants
const W = 13.333, H = 7.5;                 // LAYOUT_WIDE
const FONT = "Times New Roman";            // latin font of every run
const FONT_EA = "宋体";                     // east-asian font of every run (patched in at save)
const MONO = "Consolas";
const DEFAULT_COLORS = {
  ACCENT: "4527A0",      // deep lab purple — frame, stamps, markers
  ACCENT_SOFT: "E8E2F5", // stamp bar / title rule
  TAKEAWAY: "DCE9D5",    // take-away bar fill
  TAKEAWAY_BD: "9DBE86", // take-away border + corner triangles
  RED: "C62828",         // ONLY: active TOC + {{kw}} in stamp claims
  WHITE: "FFFFFF",
  DARK: "1A1A1A",
  GRAY: "555555",
  GRAY_LIGHT: "999999",
  BORDER: "BFBFBF",
  OURS_ROW: "F1EDF9",    // light purple fill for "our method" table rows
};
const CONTENT_TOP = 1.6;     // first y below the title rule
const CONTENT_BOTTOM = 6.95; // last usable y above page number / source line

// ---------------------------------------------------------------- text metrics
function charEm(ch) {
  const c = ch.codePointAt(0);
  if ((c >= 0x2e80 && c <= 0x9fff) || (c >= 0xf900 && c <= 0xfaff) ||
      (c >= 0xff00 && c <= 0xffef) || (c >= 0x3000 && c <= 0x303f)) return 1.0;
  if (ch === " ") return 0.25;
  if (/[A-Z]/.test(ch)) return 0.68;
  if (/[a-z0-9]/.test(ch)) return 0.5;
  if (/[.,:;'!|()\[\]]/.test(ch)) return 0.3;
  return 0.6;
}
const stripKw = (s) => String(s).replace(/\{\{(.+?)\}\}/g, "$1");
function textW(s, pt, bold) {
  let em = 0;
  for (const ch of stripKw(s)) em += charEm(ch);
  return (em * pt / 72) * (bold ? 1.06 : 1);
}
function nLines(s, pt, boxW, bold) {
  if (!s) return 1;
  return String(s).split("\n").reduce((n, part) => n + Math.max(1, Math.ceil(textW(part, pt, bold) / (boxW * 0.96))), 0);
}
const lineH = (pt) => pt * 1.22 / 72;
const hasCJK = (s) => /[⺀-鿿＀-￯　-〿]/.test(s);

function parseKw(text) {
  const out = []; const re = /\{\{(.+?)\}\}/g; let last = 0, m;
  text = String(text);
  while ((m = re.exec(text)) !== null) {
    if (m.index > last) out.push({ t: text.slice(last, m.index), kw: false });
    out.push({ t: m[1], kw: true });
    last = m.index + m[0].length;
  }
  if (last < text.length) out.push({ t: text.slice(last), kw: false });
  return out;
}
// Build pptxgenjs runs from a string with {{kw}} markup.
function runs(text, opts, kwOpts) {
  return parseKw(text).map((p) => ({
    text: p.t,
    options: { fontFace: FONT, lang: hasCJK(p.t) ? "zh-CN" : "en-US", ...opts, ...(p.kw ? kwOpts : {}) },
  }));
}

function pngSize(p) {
  const b = fs.readFileSync(p);
  if (b.toString("ascii", 1, 4) === "PNG") return { w: b.readUInt32BE(16), h: b.readUInt32BE(20) };
  // minimal JPEG SOF scan
  let i = 2;
  while (i < b.length) {
    if (b[i] !== 0xff) { i++; continue; }
    const marker = b[i + 1];
    const len = b.readUInt16BE(i + 2);
    if (marker >= 0xc0 && marker <= 0xc3) return { w: b.readUInt16BE(i + 7), h: b.readUInt16BE(i + 5) };
    i += 2 + len;
  }
  throw new Error("Unsupported image (use PNG or JPEG): " + p);
}

function mix(hexA, hexB, t) { // t=0 -> A, t=1 -> B
  const a = parseInt(hexA, 16), b = parseInt(hexB, 16);
  const ch = (v, s) => (v >> s) & 255;
  const m = (s) => Math.round(ch(a, s) * (1 - t) + ch(b, s) * t);
  return ((1 << 24) + (m(16) << 16) + (m(8) << 8) + m(0)).toString(16).slice(1).toUpperCase();
}

// ============================================================================
function createDeck(cfg) {
  const C = { ...DEFAULT_COLORS, ...(cfg.colors || {}) };
  if (cfg.accent) C.ACCENT = cfg.accent;
  for (const [k, v] of Object.entries(C)) {
    if (String(v).startsWith("#")) throw new Error(`Color ${k} must not start with '#': ${v}`);
  }
  const TOC = cfg.toc || [];
  const badge = cfg.badge || { cn: "", en: "" };
  // Unit logos: up to 2 entries, each a PNG/JPEG path or "placeholder".
  const logos = (cfg.logos || []).slice(0, 2);
  const logoOn = cfg.logoOn || "all"; // "all" = cover + content pages, "cover" = cover only
  const pres = new pptxgen();
  pres.layout = "LAYOUT_WIDE";
  pres.title = cfg.title || "研究报告";
  pres.author = cfg.author || "";

  const warnings = [];
  let pageNo = 0;
  const warn = (msg) => { const s = `[WARN] slide ${pageNo}: ${msg}`; warnings.push(s); console.warn(s); };
  const shape = (slide, type, o) => slide.addShape(pres.shapes[type], o);

  function newSlide() { pageNo += 1; const s = pres.addSlide(); s.background = { color: C.WHITE }; return s; }

  // ----------------------------------------------------------- logos
  // Draw logos right-aligned ending at xRight, all with height h. Returns the group's left x.
  function drawLogos(slide, xRight, y, h, maxW) {
    let x = xRight;
    const gap = h * 0.35;
    for (let i = logos.length - 1; i >= 0; i--) {
      const lg = logos[i];
      if (lg === "placeholder") {
        const w = h * 3.0;
        x -= w;
        shape(slide, "RECTANGLE", { x, y, w, h, fill: { color: "FAFAFA" }, line: { color: C.GRAY_LIGHT, width: 0.75, dashType: "dash" } });
        slide.addText(runs("单位 Logo", { fontSize: Math.max(9, Math.round(h * 16)), color: C.GRAY_LIGHT }), { x, y, w, h, align: "center", valign: "middle", margin: 0 });
      } else if (fs.existsSync(lg)) {
        const sz = pngSize(lg);
        let w = h * sz.w / sz.h;
        if (w > maxW) { warn("logo is very wide; crop its whitespace: " + lg); w = maxW; }
        x -= w;
        slide.addImage({ path: lg, x, y, w, h: w * sz.h / sz.w });
      } else {
        warn("logo not found: " + lg);
        continue;
      }
      x -= gap;
    }
    return x + gap;
  }

  // ----------------------------------------------------------- page frame
  function frame(slide, title, opt = {}) {
    shape(slide, "RECTANGLE", { x: 0, y: 0, w: 0.35, h: 1.6, fill: { color: C.ACCENT }, line: { type: "none" } });
    shape(slide, "RECTANGLE", { x: 0.35, y: 1.28, w: W - 0.7, h: 0.03, fill: { color: C.ACCENT_SOFT }, line: { type: "none" } });
    const withLogo = logos.length > 0 && logoOn === "all";
    if (withLogo) drawLogos(slide, W - 0.3, 0.22, 0.46, 2.6);
    if (badge.cn || badge.en) {
      slide.addText([
        ...runs(badge.cn || "", { fontSize: 11, bold: true, color: C.ACCENT }),
        ...runs("   |   ", { fontSize: 11, color: C.GRAY_LIGHT }),
        ...runs(badge.en || "", { fontSize: 11, italic: true, color: C.GRAY }),
      ], { x: W - 4.3, y: withLogo ? 0.8 : 0.35, w: 4.0, h: withLogo ? 0.32 : 0.4, align: "right", valign: "middle", margin: 0 });
    }
    if (title != null) {
      const boxW = W - 5.0;
      let pt = 32;
      while (pt > 26 && textW(title, pt, true) > boxW * 0.97) pt -= 1;
      if (textW(title, pt, true) > boxW * 0.97) warn(`title too long: "${stripKw(title)}"`);
      slide.addText(runs(title, { fontSize: pt, bold: true, color: C.DARK }, {}), {
        x: 0.55, y: 0.45, w: boxW, h: 0.75, align: "left", valign: "middle", margin: 0,
      });
    }
    slide.addText(String(pageNo), {
      x: W - 0.75, y: H - 0.45, w: 0.45, h: 0.3, fontSize: 11, color: C.GRAY_LIGHT, fontFace: FONT,
      align: "right", valign: "middle", margin: 0,
    });
    if (opt.source) {
      slide.addText(runs(opt.source, { fontSize: 10, italic: true, color: C.GRAY_LIGHT }), {
        x: 0.55, y: H - 0.45, w: W - 2.0, h: 0.3, align: "left", valign: "middle", margin: 0,
      });
    }
    if (opt.notes) slide.addNotes(stripKw(opt.notes));
  }

  // ----------------------------------------------------------- stamp block
  // label: ["问题","描述"]  claims: ["... {{kw}} ..."]
  function stampBlock(slide, label, claims, y) {
    const x = 0.55, labelW = 1.2, barX = x + labelW, barW = W - barX - 0.55;
    const tW = barW - 0.4, pt = 17;
    claims = claims || [];
    let lines = 0;
    for (const c of claims) lines += nLines("•  " + c, pt, tW);
    if (claims.length > 2) warn("stamp has more than 2 claims; keep it to 1–2");
    if (lines > 3) warn("stamp claims wrap to " + lines + " lines; shorten them");
    const h = Math.max(0.85, lines * lineH(pt) * 1.08 + 0.32);
    shape(slide, "RECTANGLE", { x, y, w: labelW, h, fill: { color: C.ACCENT }, line: { type: "none" } });
    const [l1, l2] = Array.isArray(label) ? label : [label, ""];
    slide.addText([
      ...runs(l1, { fontSize: 20, bold: true, color: C.WHITE, breakLine: !!l2 }),
      ...(l2 ? runs(l2, { fontSize: 20, bold: true, color: C.WHITE }) : []),
    ], { x, y, w: labelW, h, align: "center", valign: "middle", margin: 0 });
    shape(slide, "RECTANGLE", { x: barX, y, w: barW, h, fill: { color: C.ACCENT_SOFT }, line: { type: "none" } });
    const rr = [];
    claims.forEach((c, i) => {
      rr.push(...runs("•  ", { fontSize: pt, bold: true, color: C.ACCENT }));
      const cr = runs(c, { fontSize: pt, color: C.DARK }, { bold: true, color: C.RED });
      if (i < claims.length - 1) cr[cr.length - 1].options.breakLine = true;
      rr.push(...cr);
    });
    if (rr.length) slide.addText(rr, { x: barX + 0.22, y: y + 0.05, w: tW, h: h - 0.1, align: "left", valign: "middle", margin: 0, paraSpaceAfter: 2 });
    return y + h;
  }

  // ----------------------------------------------------------- bullet tree
  // items: [{cn, en?, subs?: [{cn?, en?}]}] ; returns bottom y
  function measureTree(items, w, s) {
    let total = 0; const rows = [];
    for (const it of items) {
      const mainText = (it.cn || "") + (it.en ? "   " + it.en : "");
      const ml = nLines(mainText, s.main, w - 0.4, true);
      const mh = Math.max(s.mainRow, ml * lineH(s.main) + 0.12);
      rows.push({ kind: "main", it, h: mh }); total += mh;
      for (const sub of it.subs || []) {
        const subText = (sub.cn || "") + (sub.en ? "   " + sub.en : "");
        const sl = nLines(subText, s.sub, w - 1.1);
        const sh = Math.max(s.subRow, sl * lineH(s.sub) + 0.1);
        rows.push({ kind: "sub", it: sub, h: sh }); total += sh;
      }
      rows.push({ kind: "gap", h: s.gap }); total += s.gap;
    }
    if (rows.length) total -= s.gap;
    return { total, rows };
  }
  function drawTree(slide, items, x, y, w, maxBottom, base, opt = {}) {
    const tries = [
      { k: 1.0, d: 0 }, { k: 0.9, d: 0 }, { k: 0.82, d: -1 }, { k: 0.76, d: -2 },
    ];
    let s, m;
    for (const t of tries) {
      s = { main: base.main + t.d, sub: base.sub + t.d, mainRow: base.mainRow * t.k, subRow: base.subRow * t.k, gap: base.gap * t.k };
      m = measureTree(items, w, s);
      if (y + m.total <= maxBottom + 1e-6) break;
    }
    if (y + m.total > maxBottom + 1e-6) warn(`bullet list overflows by ${(y + m.total - maxBottom).toFixed(2)}in — split the page or cut text`);
    if (opt.center) y = y + Math.max(0, (maxBottom - y - m.total) / 2);
    for (const r of m.rows) {
      if (r.kind === "gap") { y += r.h; continue; }
      if (r.kind === "main") {
        const sq = 0.22;
        shape(slide, "RECTANGLE", { x, y: y + (lineH(s.main) + 0.12 - sq) / 2, w: sq, h: sq, fill: { type: "none" }, line: { color: C.ACCENT, width: 2 } });
        const rr = [];
        if (r.it.cn) rr.push(...runs(r.it.cn, { fontSize: s.main, bold: true, color: C.DARK }, { color: C.ACCENT }));
        if (r.it.en) rr.push(...runs((r.it.cn ? "   " : "") + r.it.en, { fontSize: s.main - 3, italic: true, color: C.GRAY }));
        slide.addText(rr, { x: x + 0.35, y: y + 0.06, w: w - 0.35, h: r.h - 0.06, align: "left", valign: "top", margin: 0 });
      } else {
        const tri = 0.16;
        shape(slide, "RIGHT_TRIANGLE", { x: x + 0.75, y: y + (lineH(s.sub) + 0.1 - tri) / 2, w: tri, h: tri, fill: { color: C.ACCENT }, line: { type: "none" } });
        const rr = [];
        if (r.it.cn) rr.push(...runs(r.it.cn, { fontSize: s.sub, color: C.DARK }, { bold: true }));
        if (r.it.en) rr.push(...runs((r.it.cn ? "   " : "") + r.it.en, { fontSize: s.sub - 1, italic: true, color: C.GRAY }));
        slide.addText(rr, { x: x + 1.05, y: y + 0.05, w: w - 1.05, h: r.h - 0.05, align: "left", valign: "top", margin: 0 });
      }
      y += r.h;
    }
    return y;
  }

  // ----------------------------------------------------------- take-away bar
  function takeawayHeight(text) {
    const pt = 15; const l = nLines(text, pt, W - 1.75);
    if (l > 3) warn("take-away runs to " + l + " lines; one sentence, ≤ 2 lines");
    return Math.max(0.72, l * lineH(pt) + 0.32);
  }
  function takeawayBar(slide, text, y, h) {
    shape(slide, "RECTANGLE", { x: 0.55, y, w: W - 1.1, h, fill: { color: C.TAKEAWAY }, line: { color: C.TAKEAWAY_BD, width: 1 } });
    shape(slide, "RIGHT_TRIANGLE", { x: 0.55, y, w: 0.16, h: 0.16, fill: { color: C.TAKEAWAY_BD }, line: { type: "none" }, flipV: true });
    shape(slide, "RIGHT_TRIANGLE", { x: W - 0.71, y: y + h - 0.16, w: 0.16, h: 0.16, fill: { color: C.TAKEAWAY_BD }, line: { type: "none" }, flipH: true });
    slide.addText(runs(text, { fontSize: 15, color: C.DARK }, { bold: true }), {
      x: 0.85, y: y + 0.08, w: W - 1.7, h: h - 0.16, align: "left", valign: "middle", margin: 0,
    });
  }
  const TAKEAWAY_BOTTOM = H - 0.5;

  // ----------------------------------------------------------- table
  // Map every cell to its real column index, honouring rowspan/colspan.
  function placeCells(rows, nCols) {
    const carry = new Array(nCols).fill(0);
    return rows.map((r) => {
      const occ = carry.map((v) => v > 0);
      const out = []; let col = 0;
      for (const cell of r) {
        while (col < nCols && occ[col]) col++;
        const isObj = typeof cell === "object" && cell !== null;
        const span = (isObj && cell.colspan) || 1;
        const rs = (isObj && cell.rowspan) || 1;
        out.push({ cell, isObj, text: isObj ? cell.text : cell, col, span, rs });
        if (rs > 1) for (let k = col; k < col + span; k++) carry[k] = rs;
        col += span;
      }
      if (col > nCols) warn(`table row has more cells than the header (${col} > ${nCols})`);
      for (let k = 0; k < nCols; k++) if (carry[k] > 0) carry[k]--;
      return out;
    });
  }

  function buildTable(spec, top, maxBottom) {
    const header = spec.header || [];
    const rows = spec.rows || [];
    const nCols = header.length;
    const totalW = W - 1.1;
    let colW = spec.colW;
    if (!colW) colW = header.map(() => totalW / nCols);
    if (colW.length !== nCols) warn("colW length differs from header length");
    const sumW = colW.reduce((a, b) => a + b, 0);
    if (Math.abs(sumW - totalW) > 0.15) colW = colW.map((v) => v * totalW / sumW);
    const align = spec.align || header.map(() => "center");
    const ours = new Set([].concat(spec.oursRow == null ? [] : spec.oursRow));
    const placed = placeCells(rows, nCols);

    // best (bold) / second best (underline) per ranked column
    const marks = {};
    for (const rk of spec.rank || []) {
      const vals = [];
      placed.forEach((r, i) => {
        const pc = r.find((p) => p.col === rk.col && p.span === 1);
        if (!pc) return;
        const v = parseFloat(String(pc.text).replace(/[^0-9.\-]/g, ""));
        if (!isNaN(v)) vals.push({ i, v });
      });
      vals.sort((a, b) => (rk.better === "low" ? a.v - b.v : b.v - a.v));
      if (vals[0]) marks[`${vals[0].i},${rk.col}`] = "best";
      if (vals[1] && vals[1].v !== vals[0].v) marks[`${vals[1].i},${rk.col}`] = "second";
    }

    const attempts = [{ fs: 14, rh: 0.42 }, { fs: 13, rh: 0.37 }, { fs: 12, rh: 0.33 }, { fs: 11, rh: 0.3 }];
    let best;
    const rowNeed = (cells, fs, rh, bold) => {
      let mx = rh;
      for (const p of cells) {
        const w = colW.slice(p.col, p.col + p.span).reduce((a, b) => a + b, 0);
        const l = nLines(String(p.text == null ? "" : p.text), fs, w - 0.12, bold);
        mx = Math.max(mx, (l * lineH(fs) + 0.12) / p.rs);
      }
      return mx;
    };
    const headPlaced = header.map((h, j) => ({ text: h, col: j, span: 1, rs: 1 }));
    for (const a of attempts) {
      const heights = [rowNeed(headPlaced, a.fs, a.rh, true)];
      placed.forEach((r, i) => heights.push(rowNeed(r, a.fs, a.rh, ours.has(i))));
      const total = heights.reduce((p, q) => p + q, 0);
      best = { ...a, heights, total };
      if (top + total <= maxBottom) break;
    }
    if (top + best.total > maxBottom + 1e-6) warn(`table overflows by ${(top + best.total - maxBottom).toFixed(2)}in — fewer rows or shorter cells`);
    // Short table + bottom-anchored take-away leaves a hole: grow body rows (max 0.56in each).
    const spare = maxBottom - (top + best.total);
    if (spare > 0.3 && rows.length) {
      const add = Math.min((spare * 0.8) / rows.length, Math.max(0, 0.56 - best.rh));
      for (let i = 1; i < best.heights.length; i++) best.heights[i] += add;
      best.total += add * rows.length;
    }

    const mk = (text, o) => {
      const s = String(text == null ? "" : text);
      const r = runs(s, { fontSize: best.fs, color: o.color || C.DARK, bold: !!o.bold, underline: o.underline ? { style: "sng" } : undefined }, { bold: true });
      return r;
    };
    const data = [];
    data.push(header.map((h, j) => ({
      text: mk(h, { color: C.WHITE, bold: true }),
      options: { fill: { color: C.ACCENT }, align: "center", valign: "middle", bold: true },
    })));
    placed.forEach((r, i) => {
      data.push(r.map((p) => {
        const cell = p.cell, isObj = p.isObj;
        const mark = p.span === 1 ? marks[`${i},${p.col}`] : undefined;
        const o = {
          align: (isObj && cell.align) || align[p.col] || "center", valign: "middle",
          fill: ours.has(i) || (isObj && cell.emph) ? { color: C.OURS_ROW } : undefined,
        };
        if (p.span > 1) o.colspan = p.span;
        if (p.rs > 1) o.rowspan = p.rs;
        const bold = ours.has(i) || mark === "best" || (isObj && cell.bold);
        return { text: mk(p.text, { bold, underline: mark === "second" }), options: o };
      }));
    });
    return { data, colW, fs: best.fs, heights: best.heights, total: best.total };
  }

  // ----------------------------------------------------------- cover left panel
  const LP = { x: 0.5, w: 3.5, top: 0.85, bottom: 6.35 }; // usable area inside the purple panel

  function drawMotif(slide, m, soft) {
    const lines = m.lines || [];
    if (!lines.length) { warn("motif has no lines"); return; }
    if (lines.length > 9) warn("motif has " + lines.length + " rows; keep it ≤ 8");
    const hi = new Set(m.highlight || []);
    const step = Math.min(0.55, (LP.bottom - LP.top - 0.5) / lines.length);
    const longest = Math.max(...lines.map((l) => l.length));
    // monospace: ~0.6em per char + 4pt char spacing
    const pt = Math.max(12, Math.min(22, Math.floor(((LP.w + 0.2) * 72 / longest - 4) / 0.6)));
    lines.forEach((line, i) => slide.addText(line, {
      x: LP.x + 0.05, y: LP.top + 0.1 + i * step, w: LP.w + 0.3, h: step * 0.92, fontSize: pt, fontFace: MONO,
      color: hi.has(i) ? C.WHITE : soft, bold: hi.has(i), charSpacing: 4, align: "left", valign: "middle", margin: 0,
    }));
    if (m.note) slide.addText(runs(m.note, { fontSize: 12, italic: true, color: soft }), {
      x: LP.x + 0.05, y: LP.top + 0.15 + lines.length * step, w: LP.w + 0.3, h: 0.35, align: "left", valign: "middle", margin: 0,
    });
  }

  function drawOverview(slide, ov, soft) {
    const steps = ov.steps || [];
    if (steps.length < 2 || steps.length > 5) warn("overview should have 2–5 steps (has " + steps.length + ")");
    let top = LP.top;
    if (ov.title) {
      slide.addText(runs(ov.title, { fontSize: 15, bold: true, color: C.WHITE, charSpacing: 2 }), { x: LP.x, y: top, w: LP.w, h: 0.4, align: "left", valign: "middle", margin: 0 });
      shape(slide, "RECTANGLE", { x: LP.x, y: top + 0.45, w: 0.6, h: 0.05, fill: { color: C.WHITE }, line: { type: "none" } });
      top += 0.75;
    }
    const n = steps.length, arrow = 0.34;
    const boxH = Math.min(0.92, (LP.bottom - top - (n - 1) * arrow) / n);
    steps.forEach((st, i) => {
      const items = st.items || [st];
      const gap = 0.16, k = items.length;
      if (k > 2) warn("overview row with more than 2 items");
      const bw = (LP.w - (k - 1) * gap) / k;
      const y = top + i * (boxH + arrow);
      items.forEach((it, j) => {
        const x = LP.x + j * (bw + gap);
        shape(slide, "RECTANGLE", { x, y, w: bw, h: boxH, fill: it.hi ? { color: C.WHITE } : { type: "none" }, line: { color: C.WHITE, width: 1.25 } });
        const lpt = k > 1 ? 14 : 16;
        if (textW(it.label || "", lpt, true) > bw - 0.12) warn(`overview label too long: "${it.label}"`);
        const rr = [...runs(it.label || "", { fontSize: lpt, bold: true, color: it.hi ? C.ACCENT : C.WHITE, breakLine: !!it.note })];
        if (it.note) rr.push(...runs(it.note, { fontSize: k > 1 ? 10.5 : 12, color: it.hi ? C.GRAY : mix(C.ACCENT, C.WHITE, 0.75) }));
        slide.addText(rr, { x: x + 0.06, y, w: bw - 0.12, h: boxH, align: "center", valign: "middle", margin: 0 });
      });
      if (i < n - 1) {
        const cx = LP.x + LP.w / 2;
        slide.addShape(pres.shapes.LINE, { x: cx, y: y + boxH + 0.05, w: 0, h: arrow - 0.1, line: { color: C.WHITE, width: 1.5, endArrowType: "triangle" } });
      }
    });
  }

  function drawLeftLogo(slide, lg, soft) {
    const cardW = LP.w, cardY = 2.0, cardH = 2.6;
    shape(slide, "ROUNDED_RECTANGLE", { x: LP.x, y: cardY, w: cardW, h: cardH, fill: { color: C.WHITE }, line: { type: "none" }, rectRadius: 0.12 });
    if (lg.path && fs.existsSync(lg.path)) {
      const sz = pngSize(lg.path);
      let w = cardW - 0.5, h = w * sz.h / sz.w;
      if (h > cardH - 0.5) { h = cardH - 0.5; w = h * sz.w / sz.h; }
      slide.addImage({ path: lg.path, x: LP.x + (cardW - w) / 2, y: cardY + (cardH - h) / 2, w, h });
    } else {
      if (lg.path !== "placeholder") warn("cover logo not found: " + lg.path);
      slide.addText(runs("单位 Logo", { fontSize: 16, color: C.GRAY_LIGHT }), { x: LP.x, y: cardY, w: cardW, h: cardH, align: "center", valign: "middle", margin: 0 });
    }
    if (lg.caption) slide.addText(runs(lg.caption, { fontSize: 14, color: C.WHITE }), { x: LP.x, y: cardY + cardH + 0.2, w: cardW, h: 0.4, align: "center", valign: "middle", margin: 0 });
  }

  // ===================================================================== API
  const api = {};

  // ---- cover
  api.cover = function (o) {
    const slide = newSlide();
    shape(slide, "RECTANGLE", { x: 0, y: 0, w: 4.5, h: H, fill: { color: C.ACCENT }, line: { type: "none" } });
    // Left panel: one of three modes (see SKILL.md §封面左栏)
    //   { type: "motif",    lines: [...], highlight: [rowIdx], note }   topic-encoding code rows
    //   { type: "overview", title, steps: [{label, note, hi} | {items: [...]}] }  direction overview
    //   { type: "logo",     path, caption }                             big unit logo on a white card
    let left = o.left;
    if (!left && o.motifLines) left = { type: "motif", lines: o.motifLines, highlight: o.motifHighlight, note: o.motifNote };
    if (!left) { warn("cover.left missing: choose motif / overview / logo (see SKILL.md)"); left = { type: "none" }; }
    const soft = mix(C.ACCENT, C.WHITE, 0.5);
    if (left.type === "motif") drawMotif(slide, left, soft);
    else if (left.type === "overview") drawOverview(slide, left, soft);
    else if (left.type === "logo") drawLeftLogo(slide, left, soft);
    const tag = o.tag || o.motifTag;
    if (tag) slide.addText(tag, {
      x: 0.55, y: 6.6, w: 3.8, h: 0.5, fontSize: 16, bold: true, italic: true, fontFace: MONO,
      color: C.WHITE, align: "left", valign: "middle", margin: 0,
    });
    const X = 5.0, BW = W - X - 0.5;
    const topLogos = logos.length && left.type !== "logo";
    if (topLogos) drawLogos(slide, W - 0.5, 0.4, 0.62, 3.2);
    let pt = 40;
    while (pt > 30 && nLines(o.titleCn, pt, BW, true) > 2) pt -= 2;
    const tl = nLines(o.titleCn, pt, BW, true);
    if (tl > 2) warn("cover title wraps to more than 2 lines");
    const th = tl * lineH(pt) + 0.1;
    let y = (tl > 1 ? 1.1 : 1.5) + (topLogos ? 0.3 : 0);
    slide.addText(runs(o.titleCn, { fontSize: pt, bold: true, color: C.ACCENT }), { x: X, y, w: BW, h: th, align: "left", valign: "middle", margin: 0 });
    y += th + 0.08;
    if (o.subtitleCn) {
      slide.addText(runs(o.subtitleCn, { fontSize: 26, color: C.DARK }), { x: X, y, w: BW, h: 0.65, align: "left", valign: "middle", margin: 0 });
      y += 0.75;
    }
    shape(slide, "RECTANGLE", { x: X, y: y + 0.05, w: 0.9, h: 0.08, fill: { color: C.ACCENT }, line: { type: "none" } });
    y += 0.3;
    for (const en of [o.subtitleEn1, o.subtitleEn2].filter(Boolean)) {
      if (textW(en, 18) > BW) warn("cover English subtitle too long: " + en);
      slide.addText(runs(en, { fontSize: 18, italic: true, color: C.GRAY }), { x: X, y, w: BW, h: 0.45, align: "left", valign: "middle", margin: 0 });
      y += 0.45;
    }
    if (y > 5.7) warn("cover header block runs into the meta area");
    shape(slide, "RECTANGLE", { x: X, y: 5.8, w: 7.5, h: 0.04, fill: { color: C.ACCENT_SOFT }, line: { type: "none" } });
    (o.meta || []).slice(0, 3).forEach(([label, value], i) => {
      slide.addText([
        ...runs(label + "：", { fontSize: 15, color: C.GRAY_LIGHT }),
        ...runs(value, { fontSize: 17, color: C.DARK }),
      ], { x: X, y: 6.0 + i * 0.45, w: BW, h: 0.4, align: "left", valign: "middle", margin: 0 });
    });
    if (o.notes) slide.addNotes(o.notes);
  };

  // ---- TOC.  toc() = full; toc(key) = section; toc(key, subKey) = sub-section
  api.toc = function (activeKey = null, activeSubKey = null, o = {}) {
    const slide = newSlide();
    frame(slide, null, { notes: o.notes });
    slide.addText(runs("目  录", { fontSize: 32, bold: true, color: C.DARK }), { x: 0.55, y: 0.45, w: 2.0, h: 0.75, align: "left", valign: "middle", margin: 0 });
    slide.addText(runs("CONTENTS", { fontSize: 18, italic: true, color: C.GRAY_LIGHT }), { x: 2.3, y: 0.55, w: 3.0, h: 0.6, align: "left", valign: "middle", margin: 0 });
    const showAll = activeKey == null;
    if (activeKey != null && !TOC.find((t) => t.key === activeKey)) warn("unknown TOC key " + activeKey);
    let k = 1;
    const base = showAll ? { main: 0.5, sub: 0.42, mcn: 20, men: 16, scn: 17, sen: 14 } : { main: 0.62, sub: 0.5, mcn: 22, men: 18, scn: 18, sen: 15 };
    const areaTop = 1.6, areaBottom = 7.0;
    const need = (f) => TOC.reduce((acc, it) => acc + base.main * f + ((showAll || it.key === activeKey) ? it.subs.length * base.sub * f : 0), 0);
    while (k > 0.7 && need(k) > areaBottom - areaTop) k -= 0.05;
    if (need(k) > areaBottom - areaTop) warn("TOC too long for one page — merge sections");
    const mainLine = base.main * k, subLine = base.sub * k;
    let y = areaTop + Math.max(0, ((areaBottom - areaTop) - need(k)) / 2);
    for (const it of TOC) {
      const active = it.key === activeKey;
      const color = active ? C.RED : C.DARK;
      const sq = 0.24;
      shape(slide, "RECTANGLE", { x: 0.85, y: y + (mainLine - sq) / 2, w: sq, h: sq, fill: { type: "none" }, line: { color, width: 2 } });
      slide.addText([
        ...runs(it.labelCn, { fontSize: base.mcn, bold: true, color }),
        ...runs("   " + (it.labelEn || ""), { fontSize: base.men, italic: true, bold: active, color }),
      ], { x: 1.2, y, w: 11.5, h: mainLine, align: "left", valign: "middle", margin: 0 });
      y += mainLine;
      if (showAll || active) {
        for (const s of it.subs || []) {
          // section TOC (no sub chosen): all subs of the active section are red.
          // sub-section TOC: only the chosen sub is red.
          const subActive = active && (activeSubKey == null || s.key === activeSubKey);
          const sc = subActive ? C.RED : C.DARK;
          const tri = 0.16;
          shape(slide, "RIGHT_TRIANGLE", { x: 1.7, y: y + (subLine - tri) / 2, w: tri, h: tri, fill: { color: sc }, line: { type: "none" } });
          slide.addText([
            ...runs(s.labelCn, { fontSize: base.scn, bold: subActive, color: sc }),
            ...runs("   " + (s.labelEn || ""), { fontSize: base.sen, italic: true, bold: subActive, color: sc }),
          ], { x: 2.0, y, w: 11.0, h: subLine, align: "left", valign: "middle", margin: 0 });
          y += subLine;
        }
      }
    }
  };
  api.section = (key, o) => api.toc(key, null, o);
  api.sub = (key, subKey, o) => {
    const sec = TOC.find((t) => t.key === key);
    if (!sec || !(sec.subs || []).find((s) => s.key === subKey)) warn(`unknown sub-section ${key}/${subKey}`);
    api.toc(key, subKey, o);
  };

  // ---- Template A: stamp + bullet tree
  api.stampSlide = function (o) {
    const slide = newSlide();
    frame(slide, o.title, o);
    const y = stampBlock(slide, o.stamp, o.claims, CONTENT_TOP);
    drawTree(slide, o.details || [], 0.75, y + 0.28, W - 1.3, CONTENT_BOTTOM,
      { main: 18, sub: 15, mainRow: 0.5, subRow: 0.4, gap: 0.1 });
  };

  // ---- Template B: (stamp) + table + take-away
  api.tableSlide = function (o) {
    const slide = newSlide();
    frame(slide, o.title, o);
    let top = CONTENT_TOP;
    if (o.stamp) top = stampBlock(slide, o.stamp, o.claims, CONTENT_TOP) + 0.25;
    if (!o.takeaway) warn("table slide without take-away — every table needs one");
    const tkH = o.takeaway ? takeawayHeight(o.takeaway) : 0;
    const tkY = TAKEAWAY_BOTTOM - tkH;
    const maxBottom = o.takeaway ? tkY - 0.25 : CONTENT_BOTTOM;
    const t = buildTable(o, top, maxBottom);
    slide.addTable(t.data, {
      x: 0.55, y: top, w: W - 1.1, colW: t.colW, rowH: t.heights,
      fontFace: FONT, fontSize: t.fs, color: C.DARK, valign: "middle",
      border: { type: "solid", pt: 0.75, color: C.BORDER }, margin: 0.05,
    });
    if (o.takeaway) takeawayBar(slide, o.takeaway, tkY, tkH);
  };

  // ---- Template D: (stamp) + paper figure + points / take-away
  // layout "side": figure left, bullet points right.  "full": figure across the page.
  api.figureSlide = function (o) {
    const slide = newSlide();
    frame(slide, o.title, o);
    let top = CONTENT_TOP;
    if (o.stamp) top = stampBlock(slide, o.stamp, o.claims, CONTENT_TOP) + 0.25;
    const tkH = o.takeaway ? takeawayHeight(o.takeaway) : 0;
    const tkY = TAKEAWAY_BOTTOM - tkH;
    const bottom = o.takeaway ? tkY - 0.2 : CONTENT_BOTTOM;
    const haveImg = !!o.image && fs.existsSync(o.image);
    if (!haveImg) warn("image not found: " + o.image + " (placeholder drawn)");
    const sz = haveImg ? pngSize(o.image) : (o.layout === "full" ? { w: 16, h: 6 } : { w: 4, h: 3 });
    const layout = o.layout || "side";
    const boxW = layout === "side" ? (o.imageW || 6.6) : W - 1.1;
    const fit = (capH) => {
      const boxH = bottom - top - capH;
      let iw = boxW, ih = boxW * sz.h / sz.w;
      if (ih > boxH) { ih = boxH; iw = boxH * sz.w / sz.h; }
      return { iw, ih, boxH };
    };
    const capPt = 11;
    let capH = o.caption ? 0.3 : 0;
    let f = fit(capH);
    const capW = () => (layout === "side" ? Math.max(f.iw + 0.4, 4.0) : Math.max(f.iw, 8.0));
    if (o.caption) {
      const l = nLines(o.caption, capPt, capW());
      if (l > 1) { capH = l * lineH(capPt) + 0.1; f = fit(capH); }
      if (nLines(o.caption, capPt, capW()) > 2) warn("figure caption longer than 2 lines — shorten it");
    }
    const { iw, ih, boxH } = f;
    if (iw < 3.0) warn("figure rendered very small (" + iw.toFixed(1) + "in wide) — use layout 'full' or a tighter crop");
    const ix = layout === "side" ? 0.55 : 0.55 + (boxW - iw) / 2;
    const iy = layout === "side" ? top + Math.max(0, (boxH - ih) / 2) : top;
    if (haveImg) {
      slide.addImage({ path: o.image, x: ix, y: iy, w: iw, h: ih });
      shape(slide, "RECTANGLE", { x: ix, y: iy, w: iw, h: ih, fill: { type: "none" }, line: { color: "E0E0E0", width: 0.75 } });
    } else {
      shape(slide, "RECTANGLE", { x: ix, y: iy, w: iw, h: ih, fill: { color: "F5F5F5" }, line: { color: C.GRAY_LIGHT, width: 1, dashType: "dash" } });
      slide.addText(runs("论文配图（缺失）\n" + path.basename(String(o.image || "")), { fontSize: 14, color: C.GRAY_LIGHT }), { x: ix, y: iy, w: iw, h: ih, align: "center", valign: "middle", margin: 0 });
    }
    if (o.caption) {
      const cw = capW();
      const cx = layout === "side" ? Math.max(0.4, ix + iw / 2 - cw / 2) : (W - cw) / 2;
      slide.addText(runs(o.caption, { fontSize: capPt, italic: true, color: C.GRAY }), {
        x: cx, y: iy + ih + 0.05, w: cw, h: capH - 0.02, align: "center", valign: "top", margin: 0,
      });
    }
    if (layout === "side" && o.points) {
      const px = ix + iw + 0.45, pw = W - 0.55 - px;
      if (pw < 3.8) warn("figure leaves only " + pw.toFixed(1) + "in for the points — lower imageW");
      drawTree(slide, o.points, px, top + 0.05, pw, bottom, { main: 17, sub: 14, mainRow: 0.46, subRow: 0.36, gap: 0.12 }, { center: true });
    }
    if (o.takeaway) takeawayBar(slide, o.takeaway, tkY, tkH);
  };

  // ---- Template C: plain list, vertically centred
  api.listSlide = function (o) {
    const slide = newSlide();
    frame(slide, o.title, o);
    drawTree(slide, o.items || [], 0.75, 1.75, W - 1.3, CONTENT_BOTTOM - 0.1,
      { main: 20, sub: 16, mainRow: 0.55, subRow: 0.44, gap: 0.16 }, { center: true });
  };

  // ---- closing
  api.closing = function (o = {}) {
    const slide = newSlide();
    shape(slide, "RECTANGLE", { x: 0, y: 2.5, w: W, h: 2.5, fill: { color: C.ACCENT }, line: { type: "none" } });
    slide.addText(runs(o.cn || "谢 谢 聆 听", { fontSize: 52, bold: true, color: C.WHITE, charSpacing: 10 }), { x: 0, y: 2.7, w: W, h: 1.2, align: "center", valign: "middle", margin: 0 });
    slide.addText(runs(o.en || "Thank You  &  Questions ?", { fontSize: 22, italic: true, color: C.WHITE }), { x: 0, y: 3.95, w: W, h: 0.7, align: "center", valign: "middle", margin: 0 });
    shape(slide, "RECTANGLE", { x: W / 2 - 0.5, y: 1.9, w: 1.0, h: 0.06, fill: { color: C.ACCENT }, line: { type: "none" } });
    shape(slide, "RECTANGLE", { x: W / 2 - 0.5, y: 5.55, w: 1.0, h: 0.06, fill: { color: C.ACCENT }, line: { type: "none" } });
    if (o.footer) slide.addText(runs(o.footer, { fontSize: 18, color: C.GRAY }), { x: 0, y: 6.2, w: W, h: 0.5, align: "center", valign: "middle", margin: 0 });
  };

  // ---- save: write, patch fonts, validate
  api.save = async function (file) {
    const buf = await pres.write({ outputType: "nodebuffer" });
    const JSZip = loadJSZip();
    const zip = await JSZip.loadAsync(buf);
    let leaks = 0;
    for (const name of Object.keys(zip.files)) {
      if (!/^ppt\/(slides|notesSlides)\/[^/]+\.xml$/.test(name)) continue;
      let xml = await zip.file(name).async("string");
      xml = xml
        .replace(/<a:latin typeface="宋体"([^>]*)\/>/g, `<a:latin typeface="${FONT}"$1/>`)
        .replace(/<a:ea typeface="Times New Roman"[^>]*\/>/g, `<a:ea typeface="${FONT_EA}" pitchFamily="2" charset="-122"/>`);
      if (name.startsWith("ppt/slides/") && /\{\{|\}\}/.test(xml.replace(/<[^>]+>/g, ""))) leaks++;
      zip.file(name, xml);
    }
    if (leaks) warnings.push(`[WARN] {{ }} braces leaked on ${leaks} slide(s)`);
    const out = await zip.generateAsync({ type: "nodebuffer", compression: "DEFLATE" });
    fs.writeFileSync(file, out);
    console.log(`saved ${file}  (${pageNo} slides)`);
    if (warnings.length) {
      console.log(`\n${warnings.length} layout warning(s) — fix before delivering:`);
      for (const w of warnings) console.log("  " + w);
      process.exitCode = 2;
    } else {
      console.log("layout check: no warnings");
    }
  };

  api.pageNo = () => pageNo;
  return api;
}

module.exports = { createDeck, W, H };
